[["api","تصميم واجهة REST مع كشف نواقص المتطلبات"],["api-design","تصميم واجهة REST مع القرارات والبدائل"],["ad","خمس نسخ لإعلان مدفوع قصير"],["ad-copy","نصان إعلانيان بحدّ أحرف"]].forEach(([i,t])=>{const d=window.DATA.find(x=>x.id===i);if(d)d.title=t});
window.DATA.push(
P("pr-review","برمجة","مراجعة طلب دمج (Pull Request)","أنت مراجع كود أول. راجع الـ diff التالي كأنه طلب دمج في مشروع {{نوع المشروع}}.\nرتّب ملاحظاتك بالخطورة: «حرج» يمنع الدمج، «مهم» يُصلح قبل الدمج، «اقتراح» اختياري.\nلكل ملاحظة اذكر الملف والسطر والسبب والحل المقترح. ابدأ بجملة تلخّص التغيير وهل هو آمن للدمج. تجاهل التفاصيل الأسلوبية التي يعالجها المنسّق الآلي.\n\nوصف التغيير:\n{{وصف التغيير}}\n\nالـ diff:\n{{المدخل}}"),
P("stacktrace","برمجة","تحليل Stack Trace","حلّل تتبّع الأخطاء (stack trace) التالي لتطبيق {{اللغة أو الإطار}}.\nحدّد: أين وقع الخطأ فعلاً لا أين ظهر، ثم السبب الجذري المرجّح مع احتمالين بديلين، ثم خطوات لتأكيد السبب (سجلات أو نقاط توقف)، ثم الإصلاح.\nلا تخمّن شيئاً غير ظاهر في المعطيات، واطلب الملف أو السطر الناقص إن احتجت.\n\nالتتبّع:\n{{المدخل}}\n\nالكود المتعلق:\n{{الكود}}"),
P("perf-optimize","برمجة","تحسين أداء كود","حسّن أداء الكود التالي ({{اللغة}}).\nابدأ بتحديد عنق الزجاجة المرجّح وتعقيد الزمن والذاكرة الحاليين، ثم قدّم نسخة محسّنة مع تعقيدها الجديد، واذكر المقايضات.\nاقترح كيف أقيس التحسّن فعلاً (أداة وأمر) قبل أن أعتمد التغيير، ولا تغيّر السلوك الخارجي للدالة.\n\nالكود:\n{{المدخل}}\n\nحجم البيانات المتوقع:\n{{حجم البيانات}}"),
P("system-design","برمجة","تصميم نظام","صمّم نظام «{{اسم النظام}}» بحجم متوقع: {{الحجم المتوقع}}.\nاتبع هذا الترتيب: المتطلبات الوظيفية وغير الوظيفية والافتراضات، ثم المكوّنات الرئيسية وتدفق البيانات، ثم نموذج البيانات، ثم عنق الزجاجة وكيف نتوسّع، ثم نقاط الفشل والمراقبة.\nلكل قرار كبير اذكر بديلاً واحداً على الأقل وسبب اختيارك.\n\nقيودي:\n{{القيود}}"),
P("adr","برمجة","سجل قرار معماري (ADR)","اكتب سجل قرار معماري (ADR) للقرار التالي: {{القرار}}.\nالأقسام: السياق، الخيارات المدروسة (مع مزايا وعيوب كل خيار)، القرار، النتائج المترتبة (الإيجابية والسلبية)، ومتى نعيد النظر فيه.\nاكتبه بإيجاز يقرؤه مطوّر جديد في دقيقتين، ولا تختلق معلومات غير مذكورة.\n\nالسياق المتاح:\n{{السياق}}"),
P("db-schema","برمجة","تصميم مخطط قاعدة بيانات","صمّم مخطط قاعدة بيانات {{نوع القاعدة}} لـ: {{وصف التطبيق}}.\nأعطني: الجداول والأعمدة وأنواعها، المفاتيح الأساسية والأجنبية، القيود (UNIQUE وNOT NULL وCHECK)، والفهارس المقترحة مع سببها، ثم أمر الإنشاء الكامل.\nاذكر القرارات التي تحتمل بديلاً (مثل التطبيع مقابل التكرار) ولماذا اخترت ما اخترت، وأي سيناريو قد يكسر التصميم.\n\nمتطلبات إضافية:\n{{متطلبات إضافية}}"),
P("sql-optimize","برمجة","تحسين استعلام SQL بطيء","هذا استعلام {{نوع القاعدة}} بطيء. حلّله واقترح تحسينه.\nاشرح لماذا هو بطيء بحسب خطة التنفيذ إن أعطيتك إياها، ثم الفهارس المقترحة (مع أمر الإنشاء)، ثم نسخة محسّنة من الاستعلام.\nنبّه إلى تأثير كل فهرس على سرعة الكتابة، وكيف أتحقق من التحسّن بـ EXPLAIN.\n\nالاستعلام:\n{{المدخل}}\n\nخطة التنفيذ (اختياري):\n{{خطة التنفيذ}}\n\nهيكل الجداول:\n{{هيكل الجداول}}"),
P("dockerfile","برمجة","كتابة Dockerfile آمن وخفيف","اكتب Dockerfile لتطبيق {{اللغة أو الإطار}}.\nالمطلوب: بناء متعدد المراحل (multi-stage)، صورة أساس صغيرة مع ذكر الإصدار، تشغيل بمستخدم غير root، استغلال ذاكرة التخزين المؤقت للطبقات بترتيب الأوامر، وملف .dockerignore مقترح.\nاشرح كل قرار في سطر، وانبّه إلى أي ثغرة شائعة قد أقع فيها.\n\nتفاصيل التطبيق:\n{{تفاصيل التطبيق}}"),
P("github-actions","برمجة","خط CI على GitHub Actions","اكتب ملف GitHub Actions لمشروع {{اللغة}} يعمل عند كل طلب دمج: تثبيت الاعتماديات مع التخزين المؤقت، الفحص الساكن، الاختبارات، والبناء.\nأضف مصفوفة إصدارات إن كانت مناسبة، وحدّد صلاحيات GITHUB_TOKEN بأدنى حدّ، وثبّت إصدارات الإجراءات.\nاشرح كل خطوة في تعليق قصير، ولا تضع أسراراً داخل الملف.\n\nأوامر المشروع:\n{{أوامر المشروع}}"),
P("bash-safe","برمجة","سكربت Bash آمن","اكتب سكربت Bash يقوم بما يلي: {{المهمة}}.\nالتزم بالممارسات الآمنة: set -euo pipefail، اقتباس كل المتغيرات، التحقق من وجود الأوامر والملفات قبل استخدامها، رسائل خطأ واضحة، ودالة تنظيف عبر trap.\nأضف سطر استخدام (usage) عند غياب المعطيات، واذكر ما يجب اختباره قبل تشغيله على بيئة حقيقية.\n\nالبيئة:\n{{البيئة}}"),
P("openapi-spec","برمجة","مواصفة OpenAPI","حوّل وصف الواجهة التالية إلى مواصفة OpenAPI 3.1 بصيغة YAML.\nأضف لكل مسار: الوصف، المعاملات، جسم الطلب، الاستجابات الناجحة والأخطاء الشائعة (400، 401، 404، 422)، ومخططات مشتركة في components بدل التكرار.\nضع أمثلة واقعية، واذكر أي افتراض اضطررت إليه.\n\nوصف الواجهة:\n{{المدخل}}"),
P("error-handling","برمجة","تحسين معالجة الأخطاء","راجع معالجة الأخطاء في الكود التالي ({{اللغة}}) وحسّنها.\nابحث عن: أخطاء تُبتلع بصمت، رسائل غير مفيدة، غياب التمييز بين أخطاء المستخدم وأخطاء النظام، موارد لا تُغلق عند الفشل، وإعادة محاولة بلا حدّ.\nقدّم النسخة المحسّنة مع تفسير موجز لكل تغيير، ولا تغيّر منطق العمل.\n\nالكود:\n{{المدخل}}"),
P("logging-add","برمجة","إضافة تسجيل (Logging) مفيد","أضف تسجيلاً (logging) للكود التالي بحيث أستطيع تشخيص المشاكل في الإنتاج.\nاستخدم المستويات بشكل صحيح، وسجّل بصيغة مهيكلة (JSON) مع معرّف طلب، ولا تسجّل أي بيانات حساسة (كلمات مرور، رموز، بيانات شخصية).\nحدّد أين أضع كل سجل ولماذا، وتجنّب الإفراط الذي يُغرق السجلات.\n\nالكود ({{اللغة}}):\n{{المدخل}}"),
P("add-types","برمجة","إضافة أنواع (TypeScript أو Type Hints)","أضف أنواعاً صريحة للكود التالي ({{اللغة}}) دون تغيير سلوكه.\nتجنّب any أو ما يعادله، واستخدم أنواعاً دقيقة (union وgeneric وreadonly) حيث تفيد، وعرّف الواجهات للهياكل المتكررة.\nاذكر الأماكن التي كشفت فيها الأنواع احتمال خطأ حقيقي، وأي قرار تركته مفتوحاً.\n\nالكود:\n{{المدخل}}")
);
window.DATA.push(
P("threat-model","برمجة","نمذجة التهديدات (STRIDE)","أجرِ نمذجة تهديدات لنظام «{{اسم النظام}}» وفق STRIDE.\nابدأ برسم نصي لتدفق البيانات وحدود الثقة، ثم لكل فئة (انتحال، عبث، إنكار، تسريب معلومات، حجب خدمة، رفع صلاحيات) اذكر التهديدات الأعلى خطراً مع احتمالها وأثرها والتخفيف المقترح.\nرتّب الإجراءات حسب الأولوية، ولا تضف تهديدات لا علاقة لها بمعماريتي.\n\nوصف المعمارية:\n{{المعمارية}}"),
P("dependency-audit","برمجة","تدقيق اعتماديات المشروع","راجع قائمة اعتماديات المشروع التالية ({{مدير الحزم}}).\nحدّد: الحزم المهجورة أو القديمة جداً، المكرّر منها أو غير الضروري، وما يمكن استبداله بميزة مدمجة في اللغة، وأي مخاطر ترخيص تهمّ مشروعاً {{نوع المشروع}}.\nلا تختلق أرقام إصدارات؛ أعطني أمر التدقيق الذي أشغّله بنفسي عند الحاجة.\n\nالقائمة:\n{{المدخل}}"),
P("legacy-understand","برمجة","فهم كود قديم (Legacy)","ورثتُ الكود التالي ولا أفهمه. ساعدني:\n١) لخّص ما يفعله في فقرة واحدة. ٢) اشرح تدفقه خطوة بخطوة. ٣) اذكر الأجزاء الغريبة أو الخطرة وسبب وجودها المحتمل. ٤) اقترح أسئلة أطرحها على من كتبه. ٥) اقترح خطة آمنة لتغطيته باختبارات قبل لمسه.\nميّز بوضوح بين ما هو ظاهر في الكود وما هو تخمين منك.\n\nالكود:\n{{المدخل}}"),
P("edge-cases","برمجة","اكتشاف الحالات الحدّية","اقرأ الدالة التالية ({{اللغة}}) وأعطني قائمة الحالات الحدّية التي قد تكسرها: مدخلات فارغة أو null، قيم سالبة أو كبيرة جداً، ترميز النص، المناطق الزمنية، التزامن، وأخطاء الشبكة إن وُجدت.\nلكل حالة اذكر المدخل المثال وما ينبغي أن يحدث، ثم اكتب اختبارات تغطيها.\n\nالدالة:\n{{المدخل}}"),
P("integration-tests","برمجة","اختبارات تكامل","اكتب اختبارات تكامل لـ {{ما يُختبر}} باستخدام {{أداة الاختبار}}.\nغطِّ المسار السعيد وحالات الفشل الأساسية، وجهّز البيانات ونظّفها قبل كل اختبار، وتجنّب الاعتماد على ترتيب التنفيذ أو على خدمات خارجية حقيقية (استخدم بدائل مناسبة).\nسمِّ كل اختبار بجملة تصف السلوك، واذكر ما لم تغطّه.\n\nالكود المعني:\n{{المدخل}}"),
P("pr-description","برمجة","وصف طلب دمج جيد","اكتب وصفاً لطلب الدمج بناءً على الـ diff التالي.\nالأقسام: ملخص في سطرين، لماذا هذا التغيير، ما الذي تغيّر (نقاط)، كيف جرى الاختبار، المخاطر وخطة التراجع، ولقطات أو أمثلة إن لزم.\nاربط الوصف بالدافع لا بتكرار الكود، ولا تذكر شيئاً غير موجود في الـ diff.\n\nالتذكرة أو الدافع:\n{{الدافع}}\n\nالـ diff:\n{{المدخل}}"),
P("postmortem","برمجة","تقرير ما بعد الحادثة","اكتب تقرير ما بعد الحادثة (postmortem) بأسلوب بلا لوم.\nالأقسام: الملخص، الأثر (من تضرر ولكم من الوقت)، الخط الزمني، السبب الجذري (اسأل «لماذا» خمس مرات)، ما نجح وما أخفق في الاستجابة، وإجراءات وقائية بمسؤول وموعد لكل إجراء.\nلا تُسمِّ أفراداً بوصفهم السبب، وحدّد صراحةً أي نقص في المعلومات.\n\nالمعطيات:\n{{المدخل}}"),
P("runbook","برمجة","دليل تشغيل (Runbook)","اكتب دليل تشغيل لمعالجة المشكلة التالية: {{المشكلة}} في خدمة {{اسم الخدمة}}.\nيتضمن: الأعراض والتنبيهات المرتبطة، خطوات التشخيص بالترتيب مع أوامر جاهزة، الإصلاحات حسب الاحتمال، متى أصعّد ولمن، وكيف أتحقق أن الخدمة تعافت.\nاكتبه ليُنفَّذ في الثالثة فجراً: قصير وواضح ومرقّم.\n\nمعلومات عن الخدمة:\n{{المعلومات}}"),
P("rtl-css","برمجة","إصلاح مشاكل RTL في الواجهة","واجهتي بالعربية (RTL) وفيها مشاكل في الاتجاه. راجع الكود التالي وحدّد وأصلح: استخدام left/right بدل الخصائص المنطقية (margin-inline-start ونحوها)، أيقونات الأسهم غير المعكوسة، محاذاة النص، ترتيب الجداول والنماذج، الأرقام والنص المختلط (bidi)، وأماكن تحتاج dir=ltr كالأكواد والروابط.\nقدّم الكود المصحّح مع سبب كل تغيير، ونبّه إلى ما يجب اختباره في المتصفح.\n\nالكود:\n{{المدخل}}"),
P("i18n-ar","برمجة","تدويل التطبيق للعربية","ساعدني في تدويل تطبيقي ({{الإطار أو المكتبة}}) ليدعم العربية بشكل صحيح.\nغطِّ: استخراج النصوص إلى ملفات ترجمة، صيغ الجمع العربية الست (صفر، مفرد، مثنى، قليل، كثير، غيره) وكيف تُعرَّف في المكتبة، تنسيق الأرقام والتواريخ (بما فيها التقويم الهجري عند الحاجة)، الاتجاه، والخطوط.\nأعطني مثالاً عملياً لمفتاح ترجمة بجمع عربي، وقائمة تحقق قبل الإطلاق.\n\nوصف التطبيق:\n{{الوصف}}"),
P("arabic-text-code","برمجة","معالجة النص العربي في الكود","اكتب دوال {{اللغة}} لمعالجة النص العربي: إزالة التشكيل والتطويل، توحيد الهمزات والألف المقصورة والتاء المربوطة عند الحاجة للبحث، تحويل الأرقام الهندية إلى الغربية والعكس، وتقسيم الكلمات بشكل صحيح.\nلكل دالة وضّح متى يُستحسن استخدامها ومتى تُفسد المعنى (مثلاً في الأسماء)، وأعطني اختبارات بأمثلة عربية فعلية.\n\nحالة الاستخدام:\n{{حالة الاستخدام}}"),
P("a11y-audit","برمجة","تدقيق إمكانية الوصول (a11y)","دقّق إمكانية الوصول في الكود التالي وفق WCAG 2.2 مستوى AA.\nافحص: النص البديل، التسميات وارتباطها بحقولها، التباين اللوني، التنقل بلوحة المفاتيح وترتيب التركيز، أدوار ARIA الزائدة أو الناقصة، ودعم قارئات الشاشة بالعربية.\nرتّب المشاكل بحسب أثرها على المستخدم، وأعطني الإصلاح لكل واحدة.\n\nالكود:\n{{المدخل}}"),
P("db-migration","برمجة","ترحيل قاعدة بيانات بأمان","خطّط لترحيل قاعدة البيانات التالي في بيئة إنتاج حيّة بدون توقف: {{وصف التغيير}} ({{نوع القاعدة}}).\nقسّمه إلى خطوات متوافقة مع الإصدار القديم (توسيع ثم ترحيل ثم تقليص)، واذكر الأقفال المتوقعة وحجم الجدول المتأثر، وخطة التراجع لكل خطوة، وكيف أتحقق من سلامة البيانات.\nنبّه إلى الأوامر الخطرة التي تقفل الجدول.\n\nالمخطط الحالي:\n{{المخطط الحالي}}"),
P("algo-explain","برمجة","حلّ مسألة خوارزمية بشرح","حلّ المسألة التالية بأسلوب يعلّمني التفكير لا الحفظ.\nابدأ بإعادة صياغتها وأمثلة صغيرة، ثم الحل البديهي وتعقيده، ثم كيف نصل إلى الحل الأمثل خطوة بخطوة، ثم الكود بـ {{اللغة}} مع تعليقات، ثم التعقيد والحالات الحدّية.\nلا تعطني الحل الأمثل مباشرة؛ ابنِ إليه.\n\nالمسألة:\n{{المدخل}}")
);
window.DATA.push(
P("system-prompt","ذكاء اصطناعي","كتابة System Prompt لتطبيقك","اكتب System Prompt لمساعد ذكاء اصطناعي في تطبيق «{{اسم التطبيق}}» يخدم {{المستخدمون}}.\nالأقسام: الدور والهدف، النبرة واللغة (والعربية المطلوبة إن وُجدت)، ما يفعله وما يرفضه، كيف يتصرف عند نقص المعلومات، صيغة المخرجات، وأمثلة قصيرة للسلوك المطلوب.\nاكتبه بجمل مباشرة بلا حشو، وضع الأشياء الحرجة في البداية والنهاية.\n\nقواعد العمل:\n{{قواعد العمل}}"),
P("prompt-improve","ذكاء اصطناعي","تحسين برومبت موجود","أنت مهندس برومبتات. حسّن البرومبت التالي.\nأولاً شخّص نقاط ضعفه (غموض، نقص سياق، مخرجات غير محددة، تعليمات متعارضة). ثم أعد كتابته، ثم اشرح كل تغيير في سطر، ثم اقترح ثلاثة مدخلات اختبار تكشف إن كان أفضل من الأصلي فعلاً.\nحافظ على هدف الأصل ولا تضف متطلبات لم أذكرها.\n\nالبرومبت:\n{{المدخل}}\n\nما أريده منه:\n{{الهدف}}"),
P("prompt-tests","ذكاء اصطناعي","حالات اختبار لبرومبت","ولّد مجموعة اختبار لبرومبتي أستخدمها لقياس جودته قبل الإطلاق.\nأعطني ٢٠ مدخلاً موزعة: عادية، حدّية، غامضة، عدائية (محاولات تجاوز التعليمات)، وفارغة أو غريبة. لكل مدخل اكتب المخرج المتوقع أو معيار قبوله بدقة.\nضعها في جدول: رقم، نوع، مدخل، معيار القبول.\n\nالبرومبت:\n{{المدخل}}\n\nالمهمة:\n{{وصف المهمة}}"),
P("llm-judge","ذكاء اصطناعي","معيار تقييم مخرجات نموذج","صمّم معيار تقييم (rubric) لمخرجات نموذج في مهمة: {{المهمة}}.\nحدّد ٤ إلى ٦ معايير قابلة للقياس (مثل الصحة، الاكتمال، الالتزام بالصيغة، سلامة اللغة العربية)، ولكل معيار مقياس من ١ إلى ٥ بوصف دقيق لكل درجة وأمثلة قصيرة.\nثم اكتب برومبت قاضٍ (LLM-as-judge) يطبّق المعيار ويُخرج JSON فيه الدرجة والتعليل المختصر لكل معيار.\n\nأمثلة على مخرجات جيدة وسيئة:\n{{الأمثلة}}"),
P("rag-design","ذكاء اصطناعي","تصميم نظام RAG","صمّم نظام RAG لـ {{وصف المحتوى}} يخدم أسئلة بالعربية.\nغطِّ: تجهيز المستندات وتقطيعها (الحجم والتداخل ولماذا)، نموذج التضمين المناسب للعربية وكيف أختاره بالتجربة، قاعدة المتجهات، الاسترجاع (هجين مع بحث نصي؟ إعادة ترتيب؟)، صياغة البرومبت مع الاستشهاد بالمصادر، وكيف أقيس الجودة.\nاذكر أخطاء RAG الشائعة وكيف أكتشفها.\n\nقيودي (ميزانية، زمن استجابة، خصوصية):\n{{القيود}}"),
P("tool-schema","ذكاء اصطناعي","تعريف أداة لاستدعاء الدوال","اكتب تعريف أداة (function calling) بصيغة JSON Schema تتيح للنموذج: {{ما تفعله الأداة}}.\nأعطني: اسماً واضحاً، ووصفاً يشرح للنموذج متى يستدعيها ومتى لا يفعل، ومعاملات بأنواع وقيود وأمثلة، وأيّها إلزامي.\nثم أعطني ثلاثة أمثلة لطلبات مستخدم يجب أن تستدعيها، وثلاثة يجب ألّا تستدعيها، وكيف أتعامل مع خطأ الأداة.\n\nتفاصيل الواجهة الخلفية:\n{{التفاصيل}}"),
P("extract-json","ذكاء اصطناعي","استخراج بيانات بصيغة JSON ثابتة","استخرج من النص التالي الحقول المطلوبة وأعدها كـ JSON صالح فقط بلا أي شرح.\nالحقول: {{الحقول}}.\nإن لم توجد قيمة اكتب null ولا تخترع، وطبّع التواريخ إلى ISO 8601 والأرقام إلى أرقام لا نصوص.\n\nالنص:\n{{المدخل}}"),
P("prompt-injection","ذكاء اصطناعي","الدفاع ضد حقن البرومبت","راجع تصميم تطبيقي الذي يمرّر محتوى خارجياً (صفحات، رسائل، ملفات) إلى نموذج لغوي، وحدّد نقاط ضعفه أمام حقن البرومبت (prompt injection).\nاذكر سيناريوهات هجوم واقعية لتطبيقي، ثم دفاعات عملية: فصل التعليمات عن البيانات، تقليل صلاحيات الأدوات، التحقق من المخرجات، تأكيد المستخدم للإجراءات الحساسة، والمراقبة.\nلا تقدّم وعداً بأن أي دفاع واحد كافٍ.\n\nوصف التطبيق وأدواته:\n{{الوصف}}"),
P("few-shot","ذكاء اصطناعي","بناء أمثلة Few-shot","ساعدني في بناء أمثلة (few-shot) لمهمة: {{المهمة}}.\nاقترح ٥ إلى ٨ أمثلة متنوعة تغطي الحالات الشائعة والحدّية بصيغة موحّدة تماماً، واذكر لماذا اخترت كل مثال، وكيف أرتّبها لتقليل التحيّز لآخر مثال.\nثم ركّب البرومبت النهائي الجاهز مع مكان واضح للمدخل الجديد.\n\nمثال واحد حقيقي لدي:\n{{مثال}}"),
P("agent-rules","ذكاء اصطناعي","ملف قواعد لمساعد البرمجة (CLAUDE.md أو Cursor Rules)","اكتب ملف قواعد لمساعد برمجة بالذكاء الاصطناعي يعمل على مشروعي ({{نوع المشروع}}).\nيشمل: نظرة موجزة على المشروع وبنيته، أوامر البناء والاختبار والتشغيل، أسلوب الكود وقواعد التسمية، ما يُمنع تغييره دون إذن، كيف يكتب الاختبارات، وصيغة رسائل الـ commit.\nاجعله أقل من ٦٠ سطراً، محدداً وقابلاً للتنفيذ، بلا نصائح عامة.\n\nمعلومات المشروع:\n{{المعلومات}}"),
P("llm-cost","ذكاء اصطناعي","خفض تكلفة استدعاءات النموذج","راجع طريقة استخدامي لنموذج لغوي في تطبيقي واقترح كيف أخفض التكلفة والزمن دون خسارة ملموسة في الجودة.\nغطِّ: اختيار النموذج المناسب لكل مهمة، تقليص البرومبت، التخزين المؤقت للبرومبت والنتائج، التجميع (batching)، تقسيم المهام، والبث (streaming) لتحسين التجربة.\nرتّب الاقتراحات بحسب الأثر مقابل الجهد، وأخبرني كيف أقيس قبل وبعد.\n\nوصف الاستخدام الحالي وأرقامه التقريبية:\n{{الوصف}}"),
P("ar-llm-eval","ذكاء اصطناعي","اختبار جودة العربية في نموذج","صمّم اختباراً لتقييم جودة نموذج لغوي بالعربية في مهمة: {{المهمة}}.\nولّد ٢٠ حالة تغطي: الفصحى واللهجات ({{اللهجات}})، الخلط مع الإنجليزية، الأسماء والمصطلحات التقنية، التشكيل، الأرقام والتواريخ، والمعلومات الثقافية المحلية.\nلكل حالة اكتب معيار القبول، وأضف قائمة بأخطاء العربية الشائعة التي أبحث عنها في المخرجات.")
);
window.FIX={
"مراجعة كود":"أنت مراجع كود خبير في {{اللغة أو الإطار}}.\nراجع الكود التالي، واذكر لكل ملاحظة: السطر، الخطورة (عالية أو متوسطة أو منخفضة)، السبب، والحل المقترح. رتّبها هكذا: أخطاء منطقية، ثغرات أمان، أداء، قابلية الصيانة.\nلا تختلق مشاكل غير موجودة؛ وإن كان الكود سليماً في جانب فقل ذلك. ثم اقترح نسخة محسّنة.\nاشرح بالعربية وأبقِ الكود والمصطلحات التقنية بالإنجليزية.\n\nسياق الكود (اختياري):\n{{السياق}}\n\nالكود:\n{{المدخل}}",
"التاريخ الهجري":"// تقويم أم القرى، وهو المعتمد رسمياً في السعودية\nnew Intl.DateTimeFormat(\"ar-SA-u-ca-islamic-umalqura\", { dateStyle: \"full\" })\n  .format(new Date());",
"توحيد رقم جوال سعودي":"import re\n\n# تحويل الأرقام الهندية والفارسية إلى لاتينية\n_DIGITS = str.maketrans(\"٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹\", \"01234567890123456789\")\n\ndef normalize_sa_phone(p: str) -> str | None:\n    digits = re.sub(r\"[^0-9]\", \"\", p.translate(_DIGITS))\n    digits = digits.lstrip(\"0\")          # 00966... أو 0555...\n    if digits.startswith(\"966\"):\n        digits = digits[3:].lstrip(\"0\")  # 966 (0)55...\n    return \"+966\" + digits if re.fullmatch(r\"5[0-9]{8}\", digits) else None",
"تنزيل نص كملف (يدعم العربي في Excel)":"// BOM يُضاف لملفات CSV فقط حتى يقرأ Excel العربية صحيحاً\nexport function download(name, text, type = \"text/csv;charset=utf-8\") {\n  const bom = type.startsWith(\"text/csv\") ? \"\\uFEFF\" : \"\";\n  const url = URL.createObjectURL(new Blob([bom + text], { type }));\n  const a = Object.assign(document.createElement(\"a\"), { href: url, download: name });\n  document.body.append(a);\n  a.click();\n  a.remove();\n  setTimeout(() => URL.revokeObjectURL(url), 1000);\n}",
"إعادة المحاولة مع تأخير متزايد":"import random\nimport time\n\ndef retry(fn, tries: int = 3, delay: float = 1.0, exceptions=(Exception,)):\n    for i in range(tries):\n        try:\n            return fn()\n        except exceptions:\n            if i == tries - 1:\n                raise\n            # تأخير متزايد مع jitter عشوائي لتجنب تزامن المحاولات\n            time.sleep(delay * (2 ** i) + random.uniform(0, delay))",
"تشابه جيب التمام":"import math\n\ndef cosine(a: list[float], b: list[float]) -> float:\n    if len(a) != len(b):\n        raise ValueError(\"المتجهان يجب أن يكونا بنفس الطول\")\n    dot = sum(x * y for x, y in zip(a, b))\n    na = math.sqrt(sum(x * x for x in a))\n    nb = math.sqrt(sum(y * y for y in b))\n    return dot / (na * nb) if na and nb else 0.0",
"تصميم واجهة REST مع القرارات والبدائل":"صمّم واجهة REST للمتطلبات التالية: المسارات، الطرق، شكل الطلب والاستجابة، ورموز الأخطاء. اذكر قراراتك الأساسية وبدائلها بإيجاز، واقترح أي تعارض أو نقص تلاحظه في المتطلبات.\n\nالمتطلبات:\n{{المدخل}}"
};
window.DATA.forEach(d=>{if(window.FIX[d.title])d.body=window.FIX[d.title]});
